    clauses = [list(c) for c in instance["clauses"]]

    def dpll(clauses, assignment):
        # assignment: dict var -> bool
        new_clauses = []
        for clause in clauses:
            remaining = []
            satisfied = False
            for lit in clause:
                v = abs(lit)
                if v in assignment:
                    if assignment[v] == (lit > 0):
                        satisfied = True
                        break
                else:
                    remaining.append(lit)
            if satisfied:
                continue
            if not remaining:
                return False  # empty clause -> conflict
            new_clauses.append(remaining)

        if not new_clauses:
            return True

        # unit propagation
        for clause in new_clauses:
            if len(clause) == 1:
                lit = clause[0]
                v = abs(lit)
                val = lit > 0
                if v in assignment and assignment[v] != val:
                    return False
                assignment = dict(assignment)
                assignment[v] = val
                return dpll(new_clauses, assignment)

        # choose a variable from the shortest clause
        shortest = min(new_clauses, key=len)
        v = abs(shortest[0])
        for val in (True, False):
            assignment = dict(assignment)
            assignment[v] = val
            if dpll(new_clauses, assignment):
                return True
        return False

    return dpll(clauses, {})


