        ({"num_vars": 3, "clauses": [[1, 1, 2], [-1], [-2]]}, False),
    ]
    for inst, expected in sat_cases:
        tests_run += 1
        Sat.validate(inst)
        got = solve_sat(inst)
        if got == expected:
            tests_passed += 1
