Simpler approach: recursive with full clause evaluation.

def solve_sat(instance):
    clauses = instance["clauses"]
    num_vars = instance["num_vars"]
    # remove duplicate literals? not needed
    def eval_clause(clause, assignment):
        # returns True if satisfied, False if falsified (all false), None otherwise
        unknown = False
        for lit in clause:
            v = abs(lit)
            if v in assignment:
                if assignment[v] == (lit > 0):
                    return True
            else:
                unknown = True
        return None if unknown else False

    def dpll(assignment):
        # unit propagation
        changed = True
        while changed:
            changed = False
            for clause in clauses:
                status = eval_clause(clause, assignment)
                if status is False:
                    return False
                if status is None:
                    # find unassigned literals
                    unassigned = [lit for lit in clause if abs(lit) not in assignment]
                    if len(unassigned) == 1:
                        lit = unassigned[0]
                        assignment[abs(lit)] = (lit > 0)
                        changed = True
        # check all clauses
        if all(eval_clause(c, assignment) is True for c in clauses):
            return True
        # pick unassigned var
        var = None
        for clause in clauses:
            if eval_clause(clause, assignment) is None:
                for lit in clause:
                    if abs(lit) not in assignment:
                        var = abs(lit); break
                break
        if var is None:
            return True
        for value in (True, False):
            new = dict(assignment)
            new[var] = value
            if dpll(new):
                return True
        return False

    return dpll({})

